bool MiningDroneAI::Return(FMiningDroneState& Drone,
    const FMiningDroneFrame& Frame, FText& Reason)
{
    if (!Authorized(Frame, Reason) || !Deployed(Drone))
        return false;
    Drone.State = EMiningDroneState::Returning;
    Drone.TargetContact = INDEX_NONE;
    Drone.bRepeatMining = false;
    Reason = INVTEXT("Drone returning to its owner.");
    return true;
}

def ReturnToDroneBay(droneIDs):
